//! Frozen acceptance tests for `mc2_sim::mission::objective_eval` (bakeoff spec `docs/bakeoff/OBJECTIVE-EVAL.md`).
//! Expected values are derived from `code/objective.cpp` / `code/objective.h`; each test cites the lines it pins.
//! Do not edit this file: implementers add their own tests elsewhere.

use mc2_sim::mission::objective_eval::*;
use mc2_sim_data::mission::{
    Action, Area, BooleanFlag, Condition, ObjectRef, Objective, ObjectiveModel, ObjectiveOrigin,
    TeamObjectives,
};

const S: ObjectiveStatus = ObjectiveStatus::Successful;
const U: ObjectiveStatus = ObjectiveStatus::Undetermined;
const F: ObjectiveStatus = ObjectiveStatus::Failed;

#[derive(Default)]
struct Mock {
    movers: Vec<MoverView>,
    wids: Vec<(i32, usize)>,
    buildings: Vec<(i32, BuildingView)>,
    home: i32,
    time: f32,
    limit: f32,
    extract: f32,
    betty: Vec<Betty>,
    actions: Vec<String>,
    shows: u32,
}

impl Mock {
    fn new() -> Self {
        Mock {
            limit: -1.0,
            extract: 1280.0,
            ..Default::default()
        }
    }
    fn add(&mut self, m: MoverView) -> usize {
        self.movers.push(m);
        self.movers.len() - 1
    }
    fn add_wid(&mut self, wid: i32, m: MoverView) {
        let i = self.add(m);
        self.wids.push((wid, i));
    }
}

impl ObjectiveWorld for Mock {
    fn num_movers(&self) -> usize {
        self.movers.len()
    }
    fn mover(&self, index: usize) -> MoverView {
        self.movers[index]
    }
    fn mover_by_ref(&self, r: &ObjectRef) -> Option<MoverView> {
        match r {
            ObjectRef::Wid(w) => self
                .wids
                .iter()
                .find(|(id, _)| id == w)
                .map(|&(_, i)| self.movers[i]),
            ObjectRef::Position { .. } => None,
        }
    }
    fn building_by_ref(&self, r: &ObjectRef) -> Option<BuildingView> {
        match r {
            ObjectRef::Wid(w) => self
                .buildings
                .iter()
                .find(|(id, _)| id == w)
                .map(|&(_, b)| b),
            ObjectRef::Position { .. } => None,
        }
    }
    fn home_commander_id(&self) -> i32 {
        self.home
    }
    fn actual_time(&self) -> f32 {
        self.time
    }
    fn time_limit(&self) -> f32 {
        self.limit
    }
    fn max_extract_unit_distance(&self) -> f32 {
        self.extract
    }
    fn play_betty(&mut self, sample: Betty) {
        self.betty.push(sample);
    }
    fn show_objectives(&mut self) {
        self.shows += 1;
    }
    fn execute_action(&mut self, team: i32, action: &Action) {
        self.actions.push(format!("{team}:{action:?}"));
    }
}

/// An alive, on-GUI mech with a normal pilot.
fn mv(team: i32, commander: i32, x: f32, y: f32) -> MoverView {
    MoverView {
        team_id: team,
        commander_id: commander,
        x,
        y,
        destroyed: false,
        disabled: false,
        pilot_status: PilotStatus::Normal,
        on_gui: true,
        recover: false,
        is_mech: true,
        air: false,
    }
}

fn dead(mut m: MoverView) -> MoverView {
    m.destroyed = true;
    m
}

fn pilot(mut m: MoverView, s: PilotStatus) -> MoverView {
    m.pilot_status = s;
    m
}

fn bld(team: i32, destroyed: bool, captured: bool) -> BuildingView {
    BuildingView {
        team_id: team,
        destroyed,
        captured,
    }
}

fn obj(conditions: Vec<Condition>) -> Objective {
    Objective {
        origin: ObjectiveOrigin::Block { index: 0 },
        title: String::new(),
        title_use_resource_string: false,
        title_resource_string_id: 0,
        description: String::new(),
        description_use_resource_string: false,
        description_resource_string_id: 0,
        priority: 1,
        resource_points: 0,
        previous_primary_objective_must_be_complete: false,
        all_previous_primary_objectives_must_be_complete: false,
        display_marker: false,
        marker_x: 0.0,
        marker_y: 0.0,
        marker_text: String::new(),
        is_hidden_trigger: false,
        activate_on_flag: false,
        activate_flag_id: String::new(),
        reset_status_on_flag: false,
        reset_status_flag_id: String::new(),
        model: ObjectiveModel::default(),
        is_active: true,
        activation_time: -1.0,
        resolved: false,
        resolved_status: 0,
        changed_status: false,
        conditions,
        actions: Vec::new(),
        failure_conditions: Vec::new(),
        failure_actions: Vec::new(),
    }
}

fn team(objectives: Vec<Objective>) -> TeamObjectives {
    TeamObjectives {
        team: 0,
        boolean_flags: Vec::new(),
        objectives,
    }
}

fn flag(id: &str, value: bool) -> Condition {
    Condition::BooleanFlagIsSet {
        flag_id: id.into(),
        value,
    }
}

fn set(id: &str, value: bool) -> Action {
    Action::SetBooleanFlag {
        flag_id: id.into(),
        value,
    }
}

fn msg(text: &str) -> Action {
    Action::DisplayTextMessage {
        message: text.into(),
    }
}

fn cs(w: &Mock, c: Condition) -> ObjectiveStatus {
    condition_status(w, &[], 0, &c)
}

fn area(x: f32, y: f32, radius: f32) -> Area {
    Area { x, y, radius }
}

// ---------------------------------------------------------------- flags (objective.h:97-131)

#[test]
fn flags_get_missing_is_false_set_appends_then_replaces() {
    let mut f = Vec::new();
    assert!(!get_flag(&f, "a"));
    set_flag(&mut f, "a", true);
    set_flag(&mut f, "b", false);
    set_flag(&mut f, "a", false);
    assert_eq!(
        f,
        vec![
            BooleanFlag {
                flag_id: "a".into(),
                value: false
            },
            BooleanFlag {
                flag_id: "b".into(),
                value: false
            }
        ]
    );
    set_flag(&mut f, "b", true);
    assert!(get_flag(&f, "b"));
}

#[test]
fn flags_are_case_sensitive() {
    // EString == EString compares with Case_Sensitive = true (estring.h:376-379).
    let mut f = Vec::new();
    set_flag(&mut f, "Gate", true);
    assert!(!get_flag(&f, "gate"));
    set_flag(&mut f, "gate", false);
    assert_eq!(f.len(), 2);
}

#[test]
fn status_codes_round_trip() {
    for s in [U, S, F] {
        assert_eq!(status_from_code(status_code(s)), s);
    }
    assert_eq!(status_code(F), 2);
    assert_eq!(status_from_code(7), U);
}

// ---------------------------------------------------------------- destroy (objective.cpp:120-160, 365-466, 511-519)

#[test]
fn destroy_all_enemy_units() {
    let mut w = Mock::new();
    w.add(mv(0, 0, 0.0, 0.0)); // own units never matter
    w.add(dead(mv(1, 1, 0.0, 0.0)));
    assert_eq!(cs(&w, Condition::DestroyAllEnemyUnits), S);
    w.add(mv(2, 2, 0.0, 0.0));
    assert_eq!(cs(&w, Condition::DestroyAllEnemyUnits), U);
    w.movers[2].disabled = true;
    assert_eq!(cs(&w, Condition::DestroyAllEnemyUnits), S);
    w.add(pilot(mv(1, 1, 0.0, 0.0), PilotStatus::Ejected));
    w.add(pilot(mv(1, 1, 0.0, 0.0), PilotStatus::Dead));
    assert_eq!(cs(&w, Condition::DestroyAllEnemyUnits), S);
    // a withdrawn pilot is not dead or disabled
    w.add(pilot(mv(1, 1, 0.0, 0.0), PilotStatus::Withdrawn));
    assert_eq!(cs(&w, Condition::DestroyAllEnemyUnits), U);
}

#[test]
fn destroy_number_of_enemy_units_counts_enemies_only() {
    let mut w = Mock::new();
    w.add(dead(mv(0, 0, 0.0, 0.0)));
    w.add(dead(mv(0, 0, 0.0, 0.0)));
    w.add(dead(mv(1, 1, 0.0, 0.0)));
    assert_eq!(cs(&w, Condition::DestroyNumberOfEnemyUnits { num: 2 }), U);
    w.add(pilot(mv(1, 1, 0.0, 0.0), PilotStatus::Ejected));
    assert_eq!(cs(&w, Condition::DestroyNumberOfEnemyUnits { num: 2 }), S);
    assert_eq!(cs(&w, Condition::DestroyNumberOfEnemyUnits { num: 0 }), S);
}

#[test]
fn destroy_specific_enemy_unit_includes_captured() {
    let mut w = Mock::new();
    w.add_wid(10, mv(1, 1, 0.0, 0.0));
    let c = || Condition::DestroySpecificEnemyUnit {
        unit: ObjectRef::Wid(10),
    };
    assert_eq!(cs(&w, c()), U);
    // MoverIsCaptured: not destroyed and on our team (objective.cpp:173-190)
    w.movers[0].team_id = 0;
    assert_eq!(cs(&w, c()), S);
    w.movers[0] = dead(mv(1, 1, 0.0, 0.0));
    assert_eq!(cs(&w, c()), S);
    // missing object: Undetermined instead of the C++ crash (module doc)
    assert_eq!(
        cs(
            &w,
            Condition::DestroySpecificEnemyUnit {
                unit: ObjectRef::Wid(99)
            }
        ),
        U
    );
}

#[test]
fn destroy_specific_structure_ignores_team() {
    let mut w = Mock::new();
    w.buildings.push((5, bld(0, false, true)));
    w.buildings.push((6, bld(1, true, false)));
    assert_eq!(
        cs(
            &w,
            Condition::DestroySpecificStructure {
                structure: ObjectRef::Wid(5)
            }
        ),
        U
    );
    assert_eq!(
        cs(
            &w,
            Condition::DestroySpecificStructure {
                structure: ObjectRef::Wid(6)
            }
        ),
        S
    );
    assert_eq!(
        cs(
            &w,
            Condition::DestroySpecificStructure {
                structure: ObjectRef::Wid(7)
            }
        ),
        U
    );
}

// ---------------------------------------------------------------- capture or destroy (objective.cpp:521-651)

#[test]
fn capture_or_destroy_all_and_number() {
    let mut w = Mock::new();
    w.add(dead(mv(1, 1, 0.0, 0.0)));
    w.add(mv(0, 0, 0.0, 0.0));
    assert_eq!(cs(&w, Condition::CaptureOrDestroyAllEnemyUnits), S);
    assert_eq!(
        cs(&w, Condition::CaptureOrDestroyNumberOfEnemyUnits { num: 1 }),
        S
    );
    assert_eq!(
        cs(&w, Condition::CaptureOrDestroyNumberOfEnemyUnits { num: 2 }),
        U
    );
    w.add(mv(1, 1, 0.0, 0.0));
    assert_eq!(cs(&w, Condition::CaptureOrDestroyAllEnemyUnits), U);
}

#[test]
fn capture_or_destroy_specific() {
    let mut w = Mock::new();
    w.add_wid(3, mv(1, 1, 0.0, 0.0));
    assert_eq!(
        cs(
            &w,
            Condition::CaptureOrDestroySpecificEnemyUnit {
                unit: ObjectRef::Wid(3)
            }
        ),
        U
    );
    w.movers[0].disabled = true;
    assert_eq!(
        cs(
            &w,
            Condition::CaptureOrDestroySpecificEnemyUnit {
                unit: ObjectRef::Wid(3)
            }
        ),
        S
    );
    w.buildings.push((4, bld(1, false, false)));
    w.buildings.push((5, bld(0, false, false)));
    w.buildings.push((6, bld(1, true, false)));
    let st = |w: &Mock, id| {
        cs(
            w,
            Condition::CaptureOrDestroySpecificStructure {
                structure: ObjectRef::Wid(id),
            },
        )
    };
    assert_eq!(st(&w, 4), U);
    assert_eq!(st(&w, 5), S); // already on our team counts (objective.cpp:641-644)
    assert_eq!(st(&w, 6), S);
}

