// ---------------------------------------------------------------- capture (objective.cpp:730-798)

#[test]
fn capture_unit() {
    let mut w = Mock::new();
    w.add_wid(1, mv(1, 1, 0.0, 0.0));
    w.add_wid(2, mv(0, 0, 0.0, 0.0));
    w.add_wid(3, dead(mv(0, 0, 0.0, 0.0)));
    let mut disabled = mv(1, 1, 0.0, 0.0);
    disabled.disabled = true;
    w.add_wid(4, disabled);
    let c = |w: &Mock, id| {
        cs(
            w,
            Condition::CaptureUnit {
                unit: ObjectRef::Wid(id),
            },
        )
    };
    assert_eq!(c(&w, 1), U);
    assert_eq!(c(&w, 2), S);
    assert_eq!(c(&w, 3), F);
    assert_eq!(c(&w, 4), U); // disabled is not destroyed
    assert_eq!(c(&w, 99), F); // the C++ null branch (objective.cpp:734)
}

#[test]
fn capture_structure() {
    let mut w = Mock::new();
    w.buildings.push((1, bld(1, false, false)));
    w.buildings.push((2, bld(0, false, true)));
    w.buildings.push((3, bld(0, true, true)));
    let c = |w: &Mock, id| {
        cs(
            w,
            Condition::CaptureStructure {
                structure: ObjectRef::Wid(id),
            },
        )
    };
    assert_eq!(c(&w, 1), U);
    assert_eq!(c(&w, 2), S);
    assert_eq!(c(&w, 3), F);
    assert_eq!(c(&w, 4), U);
}

// ---------------------------------------------------------------- guard (objective.cpp:834-866)

#[test]
fn guard_specific_unit_never_succeeds() {
    let mut w = Mock::new();
    w.add_wid(1, mv(0, 0, 0.0, 0.0));
    w.add_wid(2, mv(1, 1, 0.0, 0.0));
    w.add_wid(3, dead(mv(0, 0, 0.0, 0.0)));
    w.time = 1.0e6;
    w.limit = 10.0;
    let c = |w: &Mock, id| {
        cs(
            w,
            Condition::GuardSpecificUnit {
                unit: ObjectRef::Wid(id),
            },
        )
    };
    assert_eq!(c(&w, 1), U);
    assert_eq!(c(&w, 2), F);
    assert_eq!(c(&w, 3), F);
    assert_eq!(c(&w, 4), U);
}

#[test]
fn guard_specific_structure_succeeds_after_time_limit() {
    let mut w = Mock::new();
    w.buildings.push((1, bld(0, false, false)));
    w.buildings.push((2, bld(1, false, true)));
    w.buildings.push((3, bld(1, false, false)));
    w.buildings.push((4, bld(0, true, false)));
    let c = |w: &Mock, id| {
        cs(
            w,
            Condition::GuardSpecificStructure {
                structure: ObjectRef::Wid(id),
            },
        )
    };
    w.time = 500.0;
    assert_eq!(c(&w, 1), U); // no time limit
    w.limit = 100.0;
    w.time = 100.0;
    assert_eq!(c(&w, 1), U); // strictly greater
    w.time = 100.5;
    assert_eq!(c(&w, 1), S);
    assert_eq!(c(&w, 2), F); // captured by someone else
    assert_eq!(c(&w, 3), S); // other team but not captured: no failure
    assert_eq!(c(&w, 4), F);
}

// ---------------------------------------------------------------- areas (objective.cpp:886-1107, SP branches)

#[test]
fn move_any_unit_to_area() {
    let mut w = Mock::new();
    let a = Condition::MoveAnyUnitToArea {
        area: area(100.0, 100.0, 10.0),
    };
    w.add(mv(0, 0, 110.0, 100.0)); // exactly on the radius: strict <
    assert_eq!(cs(&w, a.clone()), U);
    let mut off_gui = mv(0, 0, 100.0, 100.0);
    off_gui.on_gui = false;
    w.add(off_gui);
    w.add(mv(0, 3, 100.0, 100.0)); // same team, other commander
    assert_eq!(cs(&w, a.clone()), U);
    w.add(dead(mv(0, 0, 105.0, 100.0))); // a destroyed unit still counts
    assert_eq!(cs(&w, a), S);
}

#[test]
fn move_all_units_to_area() {
    let mut w = Mock::new();
    let a = Condition::MoveAllUnitsToArea {
        area: area(0.0, 0.0, 10.0),
    };
    assert_eq!(cs(&w, a.clone()), S); // nobody to check
    w.add(mv(0, 0, 10.0, 0.0)); // on the radius: only > fails
    w.add(mv(1, 1, 500.0, 0.0)); // not ours
    let mut rec = mv(0, 0, 500.0, 0.0);
    rec.recover = true;
    w.add(rec);
    assert_eq!(cs(&w, a.clone()), S);
    w.add(dead(mv(0, 0, 50.0, 0.0))); // dead units are not skipped here
    assert_eq!(cs(&w, a), U);
}

#[test]
fn move_all_surviving_units_to_area() {
    let mut w = Mock::new();
    let a = Condition::MoveAllSurvivingUnitsToArea {
        area: area(0.0, 0.0, 10.0),
    };
    w.add(mv(0, 0, 3.0, 4.0));
    w.add(dead(mv(0, 0, 50.0, 0.0)));
    w.add(pilot(mv(0, 0, 50.0, 0.0), PilotStatus::Withdrawn));
    assert_eq!(cs(&w, a.clone()), S);
    w.add(mv(0, 0, 0.0, 11.0));
    assert_eq!(cs(&w, a), U);
}

#[test]
fn move_all_surviving_mechs_to_area_and_enemy_clearance() {
    let mut w = Mock::new();
    let a = Condition::MoveAllSurvivingMechsToArea {
        area: area(0.0, 0.0, 100.0),
    };
    w.add(mv(0, 0, 10.0, 0.0));
    let mut vehicle = mv(0, 0, 900.0, 0.0);
    vehicle.is_mech = false; // only mechs must be inside
    w.add(vehicle);
    let mut air = mv(0, 0, 900.0, 0.0);
    air.air = true;
    w.add(air);
    assert_eq!(cs(&w, a.clone()), S);
    // any live non-home-commander mover inside MaxExtractUnitDistance blocks it (strict <), vehicles included
    let mut enemy = mv(1, 1, 1000.0, 0.0);
    enemy.is_mech = false;
    let e = w.add(enemy);
    assert_eq!(cs(&w, a.clone()), U);
    w.movers[e].x = 1280.0;
    assert_eq!(cs(&w, a.clone()), S);
    w.movers[e] = dead(mv(1, 1, 5.0, 0.0));
    assert_eq!(cs(&w, a.clone()), S);
    // an ally under another commander counts as well
    w.add(mv(0, 2, 20.0, 0.0));
    assert_eq!(cs(&w, a.clone()), U);
    w.extract = 10.0;
    assert_eq!(cs(&w, a), S);
}

