// ---------------------------------------------------------------- CObjective::Status() (objective.cpp:1869-1942)

#[test]
fn inactive_objective_is_undetermined_without_side_effects() {
    let mut w = Mock::new();
    let mut o = obj(vec![]);
    o.is_active = false;
    o.actions.push(msg("hi"));
    let mut t = team(vec![o]);
    assert_eq!(objective_status(&mut w, &mut t, 0), U);
    assert!(!t.objectives[0].resolved && w.actions.is_empty() && w.betty.is_empty());
}

#[test]
fn success_is_sticky_and_actions_run_once_in_order() {
    let mut w = Mock::new();
    let mut o = obj(vec![flag("go", true)]);
    o.actions = vec![msg("one"), set("done", true), msg("two")];
    let mut t = team(vec![o]);
    assert_eq!(objective_status(&mut w, &mut t, 0), U);
    assert!(!t.objectives[0].changed_status && w.actions.is_empty());
    set_flag(&mut t.boolean_flags, "go", true);
    assert_eq!(objective_status(&mut w, &mut t, 0), S);
    let o = &t.objectives[0];
    assert!(o.resolved && o.changed_status && o.resolved_status == 1);
    assert_eq!(w.betty, vec![Betty::ObjectiveComplete]);
    assert_eq!(w.actions.len(), 2);
    assert!(
        w.actions[0].starts_with("0:")
            && w.actions[0].contains("one")
            && w.actions[1].contains("two")
    );
    assert!(get_flag(&t.boolean_flags, "done"));
    // conditions no longer hold, but the result is sticky and nothing runs again
    set_flag(&mut t.boolean_flags, "go", false);
    assert_eq!(objective_status(&mut w, &mut t, 0), S);
    assert_eq!(w.actions.len(), 2);
    assert_eq!(w.betty.len(), 1);
}

#[test]
fn hidden_trigger_runs_actions_without_betty() {
    let mut w = Mock::new();
    let mut o = obj(vec![]);
    o.is_hidden_trigger = true;
    o.actions.push(msg("a"));
    let mut t = team(vec![o]);
    // no conditions: the status starts as Successful (objective.cpp:1877)
    assert_eq!(objective_status(&mut w, &mut t, 0), S);
    assert!(w.betty.is_empty());
    assert_eq!(w.actions.len(), 1);
}

#[test]
fn failed_condition_fails_and_runs_failure_actions() {
    let mut w = Mock::new();
    w.add_wid(1, dead(mv(0, 0, 0.0, 0.0)));
    let mut o = obj(vec![
        flag("pending", true),
        Condition::CaptureUnit {
            unit: ObjectRef::Wid(1),
        },
    ]);
    o.actions.push(msg("win"));
    o.failure_actions = vec![msg("lose"), set("lost", true)];
    let mut t = team(vec![o]);
    assert_eq!(objective_status(&mut w, &mut t, 0), F);
    assert_eq!(t.objectives[0].resolved_status, 2);
    assert_eq!(w.betty, vec![Betty::CannotCompleteObjective]);
    assert_eq!(w.actions.len(), 1);
    assert!(w.actions[0].contains("lose"));
    assert!(get_flag(&t.boolean_flags, "lost"));
}

#[test]
fn failure_conditions_must_all_hold() {
    let mut w = Mock::new();
    let mk = |fc: Vec<Condition>| {
        let mut o = obj(vec![flag("win", true)]);
        o.failure_conditions = fc;
        o.failure_actions.push(msg("lose"));
        team(vec![o])
    };
    // success pending, failure list all Successful -> Failed
    let mut t = mk(vec![flag("a", true), flag("b", true)]);
    t.boolean_flags = vec![
        BooleanFlag {
            flag_id: "a".into(),
            value: true,
        },
        BooleanFlag {
            flag_id: "b".into(),
            value: true,
        },
    ];
    assert_eq!(objective_status(&mut w, &mut t, 0), F);
    // one failure condition undetermined -> not failed
    let mut t = mk(vec![flag("a", true), flag("b", true)]);
    t.boolean_flags = vec![BooleanFlag {
        flag_id: "a".into(),
        value: true,
    }];
    assert_eq!(objective_status(&mut w, &mut t, 0), U);
    // a failure condition that itself Failed does not fail the objective
    let mut t = mk(vec![Condition::CaptureUnit {
        unit: ObjectRef::Wid(77),
    }]);
    assert_eq!(objective_status(&mut w, &mut t, 0), U);
    // success conditions met AND failure list met -> failure wins
    let mut t = mk(vec![flag("a", true)]);
    t.boolean_flags = vec![
        BooleanFlag {
            flag_id: "win".into(),
            value: true,
        },
        BooleanFlag {
            flag_id: "a".into(),
            value: true,
        },
    ];
    assert_eq!(objective_status(&mut w, &mut t, 0), F);
}

// ---------------------------------------------------------------- setter and change queries (objective.cpp:1991-2035)

#[test]
fn status_setter() {
    let mut o = obj(vec![]);
    set_objective_status(&mut o, S);
    assert!(o.resolved && o.changed_status && o.resolved_status == 1);
    set_objective_status(&mut o, U);
    assert!(!o.resolved && o.changed_status && o.resolved_status == 0);
    set_objective_status(&mut o, F);
    assert!(o.resolved && o.resolved_status == 2);
}

#[test]
fn change_queries_consume_the_flag_either_way() {
    let mut o = obj(vec![]);
    set_objective_status(&mut o, S);
    assert!(!status_changed_failed(&mut o)); // consumed by the wrong query
    assert!(!status_changed_success(&mut o));
    set_objective_status(&mut o, S);
    assert!(status_changed_success(&mut o));
    assert!(!status_changed_success(&mut o));
    set_objective_status(&mut o, F);
    o.is_active = false;
    assert!(!status_changed_failed(&mut o)); // inactive: false, not consumed
    o.is_active = true;
    assert!(status_changed_failed(&mut o));
}

