#[test]
fn team_status_primaries_and_secondaries() {
    let mut w = Mock::new();
    let mut secondary = obj(vec![Condition::CaptureUnit {
        unit: ObjectRef::Wid(5),
    }]);
    secondary.priority = 2;
    let mut t = team(vec![obj(vec![]), secondary, obj(vec![flag("p2", true)])]);
    assert_eq!(team_status(&mut w, &mut t), U);
    assert_eq!(t.objectives[1].resolved_status, 2); // secondaries are still evaluated
    set_flag(&mut t.boolean_flags, "p2", true);
    assert_eq!(team_status(&mut w, &mut t), S); // a failed secondary does not fail the team
}

#[test]
fn team_status_stops_at_first_failed_primary() {
    let mut w = Mock::new();
    let mut later = obj(vec![]);
    later.actions.push(msg("later"));
    let mut t = team(vec![
        obj(vec![Condition::CaptureUnit {
            unit: ObjectRef::Wid(9),
        }]),
        later,
    ]);
    assert_eq!(team_status(&mut w, &mut t), F);
    assert!(!t.objectives[1].resolved);
    assert!(w.actions.is_empty());
}

#[test]
fn team_status_activation_on_flag() {
    let mut w = Mock::new();
    w.time = 42.0;
    let mut gated = obj(vec![]);
    gated.is_active = false;
    gated.activate_on_flag = true;
    gated.activate_flag_id = "phase2".into();
    let mut never = obj(vec![flag("x", true)]);
    never.is_active = false; // inactive primary without activate_on_flag is ignored
    let mut t = team(vec![obj(vec![]), gated, never]);
    assert_eq!(team_status(&mut w, &mut t), U); // inactive gated primary holds the mission open
    assert_eq!(w.shows, 0);
    set_flag(&mut t.boolean_flags, "phase2", true);
    assert_eq!(team_status(&mut w, &mut t), U); // activated this pass but not evaluated yet
    assert!(t.objectives[1].is_active && !t.objectives[1].resolved);
    assert_eq!(t.objectives[1].activation_time, 42.0);
    assert_eq!(w.shows, 1);
    assert_eq!(team_status(&mut w, &mut t), S);
}

#[test]
fn team_status_reset_flag_reevaluates_in_same_pass() {
    let mut w = Mock::new();
    let mut o = obj(vec![]);
    o.reset_status_on_flag = true;
    o.reset_status_flag_id = "again".into();
    o.actions.push(msg("a"));
    let mut t = team(vec![o]);
    assert_eq!(team_status(&mut w, &mut t), S);
    assert_eq!(w.actions.len(), 1);
    set_flag(&mut t.boolean_flags, "again", true);
    assert_eq!(team_status(&mut w, &mut t), S);
    assert!(!get_flag(&t.boolean_flags, "again"));
    assert_eq!(w.actions.len(), 2); // reset, then resolved again with its actions
    assert_eq!(w.betty.len(), 2);
    assert_eq!(w.shows, 0); // CObjectives::Status leaves the reset display refresh commented out
}

#[test]
fn team_status_previous_primary_qualifiers() {
    let mut w = Mock::new();
    let mut needs_prev = obj(vec![]);
    needs_prev.previous_primary_objective_must_be_complete = true;
    let mut needs_all = obj(vec![]);
    needs_all.all_previous_primary_objectives_must_be_complete = true;
    let mut t = team(vec![obj(vec![flag("first", true)]), needs_prev, needs_all]);
    assert_eq!(team_status(&mut w, &mut t), U);
    assert!(!t.objectives[1].resolved && !t.objectives[2].resolved);
    set_flag(&mut t.boolean_flags, "first", true);
    assert_eq!(team_status(&mut w, &mut t), S);
    assert!(t.objectives[1].resolved && t.objectives[2].resolved);
}

#[test]
fn previous_primary_tracks_primaries_only() {
    let mut w = Mock::new();
    let mut pending_secondary = obj(vec![flag("never", true)]);
    pending_secondary.priority = 2;
    let mut needs_prev = obj(vec![]);
    needs_prev.previous_primary_objective_must_be_complete = true;
    let mut t = team(vec![obj(vec![]), pending_secondary, needs_prev]);
    // the previous *primary* (index 0) is done; the pending secondary does not block
    assert_eq!(team_status(&mut w, &mut t), S);
    assert!(t.objectives[2].resolved);
}

